// Some portions generated by Claude
package org.eclipse.rdf4j.spin.function;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.algebra.FunctionCall;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.ScalarEvaluationEffects;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.ScalarEvaluationEffects.Effect;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class SpinFunctionTest {

	private final List<SpinFunction> registered = new ArrayList<>();

	@AfterEach
	void unregister() {
		registered.forEach(FunctionRegistry.getInstance()::remove);
	}

	@Test
	void deterministicBodyIsRepeatable() {
		SpinFunction function = function("urn:test:spin:upper", "SELECT ?r WHERE { BIND(UCASE(STR(?arg1)) AS ?r) }");

		assertThat(function.mustReturnDifferentResult()).isFalse();
	}

	@Test
	void registeredDeterministicFunctionStaysRepeatableForTheOptimizer() {
		SpinFunction function = register(
				function("urn:test:spin:upper", "SELECT ?r WHERE { BIND(UCASE(STR(?arg1)) AS ?r) }"));

		assertThat(ScalarEvaluationEffects.effectOf(new FunctionCall(function.getURI(), new Var("value"))))
				.isEqualTo(Effect.REPEATABLE);
	}

	@Test
	void volatileBodyIsVolatile() {
		SpinFunction function = function("urn:test:spin:random", "SELECT ?r WHERE { BIND(RAND() AS ?r) }");

		assertThat(function.mustReturnDifferentResult()).isTrue();
	}

	@Test
	void queryStableBodyIsVolatileBecauseEveryCallEvaluatesAFreshQuery() {
		SpinFunction function = function("urn:test:spin:now", "SELECT ?r WHERE { BIND(NOW() AS ?r) }");

		assertThat(function.mustReturnDifferentResult()).isTrue();
	}

	@Test
	void bodyCallingAVolatileSpinFunctionIsVolatile() {
		register(function("urn:test:spin:random", "SELECT ?r WHERE { BIND(RAND() AS ?r) }"));
		SpinFunction caller = function("urn:test:spin:caller",
				"SELECT ?r WHERE { BIND(<urn:test:spin:random>(?arg1) AS ?r) }");

		assertThat(caller.mustReturnDifferentResult()).isTrue();
	}

	@Test
	void selfRecursiveBodyIsClassifiedWithoutUnboundedRecursion() {
		SpinFunction recursive = register(function("urn:test:spin:recursive",
				"SELECT ?r WHERE { BIND(IF(?arg1 > 0, <urn:test:spin:recursive>(?arg1 - 1), 0) AS ?r) }"));

		assertThat(recursive.mustReturnDifferentResult()).isFalse();
	}

	@Test
	void missingBodyIsNotAssumedRepeatable() {
		assertThat(new SpinFunction("urn:test:spin:unparsed").mustReturnDifferentResult()).isTrue();
	}

	private SpinFunction register(SpinFunction function) {
		FunctionRegistry.getInstance().add(function);
		registered.add(function);
		return function;
	}

	private static SpinFunction function(String iri, String body) {
		SpinFunction function = new SpinFunction(iri);
		function.setParsedQuery(QueryParserUtil.parseQuery(QueryLanguage.SPARQL, body, null));
		return function;
	}
}
